-- Đưa section `equipment` (popup thông số từng máy ở section Thiết bị) vào database
-- ĐÃ seed. Database mới nhận nó từ seed. Hai chốt, cùng lý do với 004:
--
--   * `WHERE EXISTS (SELECT 1 FROM section)`: trên database TRỐNG migration chạy trước
--     seed; chèn lúc đó thì seed từ chối chạy.
--   * `NOT EXISTS (... AND locale = ...)` THEO TỪNG NGÔN NGỮ: chốt theo key thôi thì
--     dòng `vi` vừa chèn làm câu `en` thấy "đã có" và bản EN không bao giờ vào.
--
-- JSON là bản ĐÓNG BĂNG của `vi.equipment` / `en.equipment` lúc viết migration, sinh
-- bằng máy. Ảnh máy KHÔNG đi đường này (SQL không xử lý file): chạy
-- `npm run seed:images` sau khi máy chủ đã áp migration.
--
-- Hai dòng mới cộng 2 vào SUM(section.rev) — bộ đệm và ETag của người xem tự làm mới.

INSERT INTO section (locale, key, json, rev, updated_at)
SELECT 'vi', 'equipment', '{"listLabel":"Các máy trong khu này","openLabel":"Xem thông số","specsTitle":"Thông số kỹ thuật","noSpecs":"Trang thiết bị của FabLab chưa công bố thông số chi tiết cho máy này.","close":"Đóng","imageAlt":"Ảnh {name}","source":"Xem trang thiết bị của FabLab","sourceUrl":"https://fablab.eiu.edu.vn/vi/thiet-bi/","items":[{"id":"form-3","facility":"printer-3d","name":"Formlabs Form 3","type":"Máy in 3D resin","specs":[{"id":"technology","label":"Công nghệ in","detail":"SLA – Stereolithography Apparatus; LFS – Low Force Stereolithography"},{"id":"print-size","label":"Kích thước vật in","detail":"145x145x185 mm (Ngang – Dọc – Cao)"},{"id":"layer","label":"Độ dày lớp in","detail":"25 – 300 µm"},{"id":"material","label":"Vật liệu","detail":"Resin"}]},{"id":"cubicon-210f","facility":"printer-3d","name":"Cubicon 210F","type":"Máy in 3D","specs":[{"id":"technology","label":"Công nghệ in","detail":"FFF – Fused Filament Fabrication"},{"id":"print-size","label":"Kích thước vật in","detail":"150x150x150 mm (Ngang – Dọc – Cao)"},{"id":"layer","label":"Độ dày lớp in","detail":"150 – 300 µm (nhỏ nhất 100 µm)"},{"id":"material-diameter","label":"Đường kính vật liệu","detail":"1.75 mm"},{"id":"material","label":"Vật liệu","detail":"ABS, PLA, TPU"},{"id":"nozzle","label":"Đường kính đầu in","detail":"0.4 mm"},{"id":"accuracy-xy","label":"Độ chính xác trục XY","detail":"6.25 µm"},{"id":"accuracy-z","label":"Độ chính xác trục Z","detail":"1.25 µm"},{"id":"nozzle-temp","label":"Nhiệt độ đầu in (tối đa)","detail":"260 °C"},{"id":"bed-temp","label":"Nhiệt độ bàn in (tối đa)","detail":"120 °C"}]},{"id":"cubicon-310f","facility":"printer-3d","name":"Cubicon 310F","type":"Máy in 3D","specs":[{"id":"technology","label":"Công nghệ in","detail":"FFF – Fused Filament Fabrication"},{"id":"print-size","label":"Kích thước vật in","detail":"240x190x200 mm (Ngang – Dọc – Cao)"},{"id":"layer","label":"Độ dày lớp in","detail":"150 – 300 µm (nhỏ nhất 100 µm)"},{"id":"material-diameter","label":"Đường kính vật liệu","detail":"1.75 mm"},{"id":"material","label":"Vật liệu","detail":"ABS, PLA, TPU"},{"id":"nozzle","label":"Đường kính đầu in","detail":"0.4 mm"},{"id":"accuracy-xy","label":"Độ chính xác trục XY","detail":"6.25 µm"},{"id":"accuracy-z","label":"Độ chính xác trục Z","detail":"1.25 µm"},{"id":"nozzle-temp","label":"Nhiệt độ đầu in (tối đa)","detail":"260 °C"},{"id":"bed-temp","label":"Nhiệt độ bàn in (tối đa)","detail":"120 °C"}]},{"id":"shining-3d","facility":"printer-3d","name":"Shining 3D","type":"Máy scan 3D","specs":[{"id":"mode","label":"Chế độ","detail":"Scan cố định – Scan tự động"},{"id":"min-size","label":"Kích thước vật nhỏ nhất","detail":"30x30x30 mm"},{"id":"max-size","label":"Kích thước vật lớn nhất","detail":"200x200x200 mm"},{"id":"speed","label":"Tốc độ scan","detail":"4 giây"},{"id":"formats","label":"Định dạng xuất","detail":"OBJ, STL, ASC, PLY"},{"id":"camera","label":"Độ phân giải camera","detail":"1.3 megapixel"},{"id":"light","label":"Nguồn sáng","detail":"Ánh sáng trắng"},{"id":"connection","label":"Kết nối","detail":"USB"}]},{"id":"epilog-mini-helix-18","facility":"laser","name":"Epilog Mini Helix 18","type":"Máy cắt laser","specs":[{"id":"table-size","label":"Kích thước bàn cắt","detail":"18″ x 12″ (457 x 305 mm)"},{"id":"thickness","label":"Độ dày vật liệu (tối đa)","detail":"4″ (102 mm)"},{"id":"power","label":"Công suất đầu phóng","detail":"40 W"},{"id":"resolution","label":"Độ phân giải","detail":"75 – 1200 DPI"},{"id":"connection","label":"Kết nối","detail":"Cáp Ethernet T-Base hoặc USB"}]},{"id":"roland-srm-20","facility":"cnc","name":"Roland SRM-20","type":"Máy phay CNC","specs":[{"id":"table-size","label":"Kích thước bàn cắt","detail":"100 x 100 mm"},{"id":"connection","label":"Kết nối","detail":"Cáp Ethernet T-Base hoặc USB"}]},{"id":"proxxon-ff500","facility":"cnc","name":"Proxxon FF500","type":"Máy phay","specs":[{"id":"machine-size","label":"Kích thước máy","detail":"400 x 125 mm, cao 780 mm"},{